import assert from "node:assert/strict";
import { test } from "node:test";

import { cartTotal } from "../src/cart.ts";
import type { Product } from "../src/catalog.ts";

const book: Product = { sku: "B1", title: "Refactoring", price: 40, category: "books", stock: 3 };
const game: Product = { sku: "G1", title: "Go", price: 20, category: "games", stock: 1 };

test("members get the member price on every line", () => {
  const total = cartTotal({ lines: [{ product: book, quantity: 1 }, { product: game, quantity: 2 }] }, true);
  assert.equal(total, 74);
});

test("a cart coupon applies once to the whole cart", () => {
  const total = cartTotal({ lines: [{ product: game, quantity: 1 }], coupon: "SAVE10" }, false);
  assert.equal(total, 10);
});
import type { Product } from "./catalog.ts";
import { getPrice } from "./pricing.ts";

export interface CartLine {
  product: Product;
  quantity: number;
}

export interface Cart {
  lines: CartLine[];
  coupon?: string;
}

export function cartTotal(cart: Cart, isMember: boolean): number {
  let total = 0;
  for (const line of cart.lines) {
    total += getPrice(line.product, isMember) * line.quantity;
  }
  if (cart.coupon) {
    total = getPrice({ price: total, category: "mixed" }, false, cart.coupon);
  }
  return Math.round(total * 100) / 100;
}
import { getPrice } from "../pricing.ts";

interface FeedRow {
  id: string;
  price: number;
}

export function feedPrices(rows: FeedRow[], coupon: string): Record<string, number> {
  const prices: Record<string, number> = {};
  for (const row of rows) {
    prices[row.id] = getPrice(row, false, coupon);
  }
  return prices;
}
import type { Product } from "../catalog.ts";
import { getPrice } from "../pricing.ts";

export function priceListRows(products: Product[]): string[] {
  return products.map(
    (product) =>
      `${product.sku};${product.title};${getPrice(product, false)};${getPrice(product, true)}`,
  );
}
import { getPrice } from "./pricing.ts";

export interface OrderLine {
  sku: string;
  unitPrice: number;
  category?: string;
  quantity: number;
}

export function lineTotals(lines: OrderLine[], isMember: boolean): number[] {
  return lines.map(
    (line) => getPrice({ price: line.unitPrice, category: line.category }, isMember) * line.quantity,
  );
}
